import { NextResponse } from 'next/server';

export async function GET() {
  // Simulate dynamic data changing on each request
  const themes = ['light', 'dark', 'system', 'sepia'];
  const randomTheme = themes[Math.floor(Math.random() * themes.length)];

  return NextResponse.json({
    theme: randomTheme,
    notifications: true,
    lastUpdated: new Date().toISOString(),
    requestId: Math.random().toString(36).substring(7)
  }, {
    // Add headers to ensure no caching at the API level as well, though the fetcher controls the cache mostly
    headers: {
      'Cache-Control': 'no-store, max-age=0'
    }
  });
}

export default async function UserDashboard() {
  try {
    // Fetch user-specific data that changes on each request
    // using cache: 'no-store' to ensure dynamic data fetching
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    const data = await res.json();

    return (
      <div className="p-4 border rounded shadow-sm">
        <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
        <div className="space-y-2">
          <p><strong>Theme Preference:</strong> {data.theme}</p>
          <p><strong>Notifications:</strong> {data.notifications ? 'On' : 'Off'}</p>
          <p className="text-sm text-gray-500">Last Updated: {data.lastUpdated}</p>
          <p className="text-xs text-gray-400">Request ID: {data.requestId}</p>
        </div>
      </div>
    );
  } catch (error) {
    console.error('Error fetching dashboard data:', error);
    return (
      <div className="p-4 border rounded shadow-sm bg-red-50">
        <h2 className="text-xl font-bold mb-2 text-red-700">User Dashboard</h2>
        <p className="text-red-600">Failed to load user preferences.</p>
      </div>
    );
  }
}

